function piezasDisponibles(categoria, estacion) {
  const scope = manifest.categorias[categoria].scope;
  if (scope === 'por_estacion') {
    return manifest.assets[estacion][categoria] || [];
  }
  // scope === 'compartido': combinar universal + exclusivos de la estacion
  const universales = manifest.assets.universal[categoria] || [];
  const exclusivas = (manifest.assets[estacion] && manifest.assets[estacion][categoria]) || [];
  return [...universales, ...exclusivas];
}
